//! Literal native-history oracles; expected biology is not generated by replay.
use super::*;
use crate::{
    construct_qc::{AnnotationAssumption, Verdict},
    documents::{
        history::{
            DocumentHistory,
            transition::{AnalysisOrigin, AnalysisProducer},
        },
        reference_edit::Operation,
    },
    material::lineage::EventBinding,
};
use collagene_model::{Feature, Location, Molecule, Topology};
use std::collections::BTreeMap;

fn cds(location: Location) -> Feature {
    Feature {
        kind: "CDS".into(),
        location,
        qualifiers: vec![],
        needs_review: false,
    }
}
fn declared(molecule: &Molecule, event: &EventBinding) -> AnnotationAssumption {
    AnnotationAssumption { feature_index: 0, source_revision: event.revision.clone(), annotation_revision: crate::construct_qc::annotation_revision(&molecule.features[0]).unwrap(), rationale: "Explicit coordinate/CDS role assumption for this comparison; not annotation-truth verification".into() }
}
fn archive(history: &DocumentHistory) -> Workspace {
    let mut workspace = Workspace {
        name: "causal literal fixture".into(),
        active_document: history.id.clone(),
        documents: vec![],
        revisions: BTreeMap::new(),
        history: vec![],
        candidates: vec![],
        active_candidate: None,
        attachments: BTreeMap::new(),
    };
    history.contribute(&mut workspace).unwrap();
    workspace.validate().unwrap();
    workspace
}
fn reviewed(location: Location) -> Vec<Operation> {
    // An authored replacement explicitly relinquishes inherited annotation identity.
    // It does not silently clear the native review flags on a clipped annotation.
    vec![
        Operation::DeleteFeature { index: 0 },
        Operation::SetFeature {
            index: None,
            feature: cds(location),
        },
    ]
}
fn case(
    dna: &str,
    location: Location,
    topology: Topology,
    actions: Vec<Operation>,
) -> (Workspace, Request) {
    let mut source = Molecule::dna("literal coding template", dna, topology).unwrap();
    source.features.push(cds(location));
    let mut history = DocumentHistory::new("document-1", source.clone()).unwrap();
    let source_event = history.binding();
    history
        .commit(actions, "Actual typed fixture actions")
        .unwrap();
    let product_event = history.binding();
    let request = Request {
        pairs: vec![CdsPair {
            id: "declared pair".into(),
            source: source_event.clone(),
            product: product_event.clone(),
            source_cds: declared(&source, &source_event),
            product_cds: declared(&history.molecule, &product_event),
            genetic_code: 1,
        }],
        ..Default::default()
    };
    (archive(&history), request)
}
fn verdict(report: &Report, rule: Rule) -> Verdict {
    report.pairs[0]
        .findings
        .iter()
        .find(|finding| finding.rule == rule)
        .unwrap()
        .verdict
        .clone()
}
#[test]
fn one_base_insertion_creates_a_definite_stop_far_beyond_the_actual_junction() {
    let mut actions = vec![Operation::ReplaceSequence {
        start: 4,
        end: 4,
        replacement: "A".into(),
    }];
    actions.extend(reviewed(Location::range(0, 22)));
    let (workspace, request) = case(
        "ATGAAACCAGGTAACGAATAA",
        Location::range(0, 21),
        Topology::Linear,
        actions,
    );
    assert_eq!(
        workspace.revisions[&request.pairs[0].product.revision]
            .sequence
            .as_str(),
        "ATGAAAACCAGGTAACGAATAA"
    );
    let report = assess(&workspace, &request).unwrap();
    assert_eq!(verdict(&report, Rule::JunctionRegister), Verdict::Fail);
    assert_eq!(
        report.pairs[0].annotation_correspondence.verdict,
        Verdict::Indeterminate
    );
    let stop = report.pairs[0]
        .new_stops
        .iter()
        .find(|stop| stop.verdict == Verdict::Fail)
        .unwrap();
    assert_eq!(stop.product_codon_index, 4);
    assert_eq!(stop.product_codon, "TAA");
    assert_eq!(
        stop.product_coordinates
            .spans()
            .into_iter()
            .map(|(a, b, _)| (a, b))
            .collect::<Vec<_>>(),
        vec![(12, 13), (13, 14), (14, 15)]
    );
    assert!(stop.parent_codon_index.is_none());
    assert!(!stop.causes.is_empty());
    assert!(
        report.pairs[0]
            .register_segments
            .iter()
            .any(|segment| segment.native_junction_proven && segment.offset_mod3 == 1)
    );
    report.validate_request(&workspace, &request).unwrap();
}
#[test]
fn compensating_deletion_restores_register_without_erasing_the_shifted_segment() {
    let mut actions = vec![
        Operation::ReplaceSequence {
            start: 4,
            end: 4,
            replacement: "A".into(),
        },
        Operation::ReplaceSequence {
            start: 10,
            end: 11,
            replacement: String::new(),
        },
    ];
    actions.extend(reviewed(Location::range(0, 21)));
    let (workspace, request) = case(
        "ATGAAACCAGGTAACGAATAA",
        Location::range(0, 21),
        Topology::Linear,
        actions,
    );
    assert_eq!(
        workspace.revisions[&request.pairs[0].product.revision]
            .sequence
            .as_str(),
        "ATGAAAACCAGTAACGAATAA"
    );
    let report = assess(&workspace, &request).unwrap();
    let segments = &report.pairs[0].register_segments;
    assert!(segments.iter().any(|segment| segment.native_junction_proven
        && segment.offset_mod3 == 1
        && segment.product_coding_start == 5));
    assert!(segments.iter().any(|segment| segment.native_junction_proven
        && segment.offset_mod3 == 0
        && segment.product_coding_start == 10));
    assert_eq!(verdict(&report, Rule::JunctionRegister), Verdict::Fail);
}
#[test]
fn literal_codon_replacement_uses_retained_parent_codon_anchors() {
    let mut actions = vec![Operation::ReplaceSequence {
        start: 3,
        end: 4,
        replacement: "T".into(),
    }];
    actions.extend(reviewed(Location::range(0, 12)));
    let (workspace, request) = case(
        "ATGCAACCCTAA",
        Location::range(0, 12),
        Topology::Linear,
        actions,
    );
    let report = assess(&workspace, &request).unwrap();
    assert_eq!(verdict(&report, Rule::JunctionRegister), Verdict::Pass);
    let stop = report.pairs[0]
        .new_stops
        .iter()
        .find(|stop| stop.verdict == Verdict::Fail)
        .unwrap();
    assert_eq!(stop.product_codon_index, 1);
    assert_eq!(stop.product_codon, "TAA");
    assert_eq!(stop.parent_codon_index, Some(1));
    assert_eq!(stop.parent_codon.as_deref(), Some("CAA"));
    assert_eq!(stop.parent_amino_acid, Some('Q'));
}
#[test]
fn an_intron_edit_preserves_joined_coding_register() {
    let mut actions = vec![Operation::ReplaceSequence {
        start: 5,
        end: 5,
        replacement: "C".into(),
    }];
    actions.extend(reviewed(Location::Join(vec![
        Location::range(0, 3),
        Location::range(8, 14),
    ])));
    let (workspace, request) = case(
        "ATGGGGGAAATAA",
        Location::Join(vec![Location::range(0, 3), Location::range(7, 13)]),
        Topology::Linear,
        actions,
    );
    let report = assess(&workspace, &request).unwrap();
    assert_eq!(verdict(&report, Rule::JunctionRegister), Verdict::Pass);
    assert!(
        report.pairs[0]
            .register_segments
            .iter()
            .all(|segment| segment.offset_mod3 == 0)
    );
    assert_eq!(verdict(&report, Rule::NewInternalStop), Verdict::Pass);
}
#[test]
fn reverse_and_circular_origin_changes_preserve_biological_coding_order() {
    for (topology, action) in [
        (Topology::Linear, Operation::ReverseComplement),
        (
            Topology::Circular,
            Operation::RotateOrigin { new_origin: 5 },
        ),
    ] {
        let (workspace, request) = case(
            "ATGAAACCCTAA",
            Location::range(0, 12),
            topology,
            vec![action],
        );
        let report = assess(&workspace, &request).unwrap();
        assert_eq!(verdict(&report, Rule::JunctionRegister), Verdict::Pass);
        assert_eq!(verdict(&report, Rule::NewInternalStop), Verdict::Pass);
        assert_eq!(
            report.pairs[0].annotation_correspondence.verdict,
            Verdict::Pass
        );
    }
}
#[test]
fn redefining_a_cds_without_a_dna_edit_does_not_fabricate_dna_causality() {
    let (workspace, request) = case(
        "ATGAAACCCTAA",
        Location::range(0, 12),
        Topology::Linear,
        reviewed(Location::range(1, 12)),
    );
    let report = assess(&workspace, &request).unwrap();
    assert_eq!(
        verdict(&report, Rule::JunctionRegister),
        Verdict::Indeterminate
    );
    assert_eq!(
        verdict(&report, Rule::NewInternalStop),
        Verdict::Indeterminate
    );
    assert!(
        report.pairs[0]
            .register_segments
            .iter()
            .all(|segment| !segment.native_junction_proven)
    );
    assert!(
        report.pairs[0]
            .new_stops
            .iter()
            .all(|stop| stop.verdict != Verdict::Fail)
    );
}
#[test]
fn unreviewed_cds_and_unretained_previews_remain_explicitly_indeterminate() {
    let (workspace, request) = case(
        "ATGCAACCCTAA",
        Location::range(0, 12),
        Topology::Linear,
        vec![Operation::ReplaceSequence {
            start: 3,
            end: 4,
            replacement: "T".into(),
        }],
    );
    let report = assess(&workspace, &request).unwrap();
    assert_eq!(
        verdict(&report, Rule::JunctionRegister),
        Verdict::Indeterminate
    );
    let mut source = Molecule::dna("source", "ATGAAACCCTAA", Topology::Linear).unwrap();
    source.features.push(cds(Location::range(0, 12)));
    let mut history = DocumentHistory::new("document-1", source.clone()).unwrap();
    let before = history.binding();
    let mut preview = source.clone();
    preview.name = "actual unretained preview".into();
    history
        .commit_analysis(
            preview,
            "Computational preview",
            AnalysisOrigin::preview(AnalysisProducer::MutationIntent, "a".repeat(64)),
            &[],
        )
        .unwrap();
    let after = history.binding();
    let request = Request {
        pairs: vec![CdsPair {
            id: "preview".into(),
            source: before.clone(),
            product: after.clone(),
            source_cds: declared(&source, &before),
            product_cds: declared(&history.molecule, &after),
            genetic_code: 1,
        }],
        ..Default::default()
    };
    let report = assess(&archive(&history), &request).unwrap();
    assert_eq!(
        verdict(&report, Rule::NativeHistory),
        Verdict::Indeterminate
    );
    assert_eq!(
        verdict(&report, Rule::NewInternalStop),
        Verdict::Indeterminate
    );
}
#[test]
fn an_exhausted_no_stop_scan_never_becomes_an_absence_pass() {
    let (workspace, mut request) = case(
        "ATGAAACCCTAA",
        Location::range(0, 12),
        Topology::Linear,
        vec![Operation::Rename {
            name: "actual renamed source".into(),
        }],
    );
    request.limits.max_work = 1;
    let report = assess(&workspace, &request).unwrap();
    assert_eq!(
        verdict(&report, Rule::NewInternalStop),
        Verdict::Indeterminate
    );
    assert!(!report.pairs[0].mapping_complete);
}
#[test]
fn exact_genetic_code_and_documentary_bindings_cannot_be_silently_replaced() {
    let mut actions = vec![Operation::ReplaceSequence {
        start: 3,
        end: 4,
        replacement: "T".into(),
    }];
    actions.extend(reviewed(Location::range(0, 12)));
    let (workspace, mut request) = case(
        "ATGCAACCCTAA",
        Location::range(0, 12),
        Topology::Linear,
        actions,
    );
    request.pairs[0].genetic_code = 6; // TAA is Q in the native table6, not a stop.
    let report = assess(&workspace, &request).unwrap();
    assert!(report.pairs[0].new_stops.is_empty());
    assert_eq!(report.pairs[0].code.descriptor.id, 6);
    let mut changed = request.clone();
    changed.pairs[0].source_cds.rationale.push('!');
    assert!(report.validate_request(&workspace, &changed).is_err());
    let mut tampered = report.clone();
    tampered.pairs[0].source_cds.annotation_revision = "f".repeat(64);
    assert!(tampered.validate_binding(&report.context_revision).is_err());
}
